    public boolean containsSubstring(String word, String substring) {
        for (int i = 0; i < word.length(); i++) {
            for (int j = 0; j < substring.length(); j++) {
                if (i + j >= word.length())
                    break;
                if (word.charAt(i + j) != substring.charAt(j)) {
                    break;
                } else {
                    if (j == substring.length() - 1) {
                        return true;
                    }
                }
            }
        }

        return false;
    }



	public int countSameCharsAtSamePosition(String word1, String word2) {
		int shortestLength;

		if (word1.length() < word2.length())
			shortestLength = word1.length();
		else
			shortestLength = word2.length();

		int sameCharsAtSamePosition = 0;

		for (int i = 0; i < shortestLength; i++) {
			if (word1.charAt(i) == word2.charAt(i)) {
				sameCharsAtSamePosition++;
			}
		}

		return sameCharsAtSamePosition;
	}



    public int countVowels(String word) {
        char[] vowels = {'a', 'e', 'i', 'o', 'u'};
        int numberOfVowels = 0;

        for (int i = 0; i < word.length(); i++) {
            for (int j = 0; j < vowels.length; j++) {
                if (word.charAt(i) == vowels[j]) {
                    numberOfVowels++;
                }
            }
        }

        return numberOfVowels;
    }



    public float arrayAverage(int[] array) {
        int counter = 0;
        int sum = 0;

        while (counter < array.length) {
            sum = sum + array[counter];
            counter = counter + 1;
        }

        float average = sum / (float) counter;
        return average;
    }



    public int CrossSum(int number) {
        int crossSum = 0;

        while (number != 0) {
            crossSum += number % 10;
            number /= 10;
        }

        return crossSum;
    }



    public int binaryToDecimal(int binaryNumber) {
        if (binaryNumber < 0)
            return -1;

        int decimalNumber = 0;
        int tempNumber = binaryNumber;
        int multiplikator = 0;

        for (int i = 0; tempNumber > 0; i++) {
            multiplikator = tempNumber % 10;
            decimalNumber = decimalNumber + multiplikator * (int) Math.pow(2, i);
            tempNumber = tempNumber / 10;
        }

        return decimalNumber;
    }



